steps = []
steps.append(fc.ManualGcode(text='PRINT_START EXTRUDER=210 BED=60 MATERIAL=PLA'))
steps.append(fc.ExtrusionGeometry(area_model='rectangle', width=0.45, height=0.3))
steps.append(fc.Printer(travel_speed=12000))
steps.append(fc.Fan(speed_percent=100))
steps.append(fc.Extruder(on=True))

_on, _feed = 1, None
for x, y, z, feed, e in MOVES:
    if e != _on:
        steps.append(fc.Extruder(on=bool(e))); _on = e
    if e and feed != _feed:
        steps.append(fc.Printer(print_speed=feed)); _feed = feed
    steps.append(fc.Point(x=x, y=y, z=z))
steps.append(fc.ManualGcode(text='PRINT_END'))


# --- G-code (for the printer) ---
gcode = fc.transform(steps, 'gcode', fc.GcodeControls(
    printer_name='generic',
    initialization_data={
        'primer': 'no_primer',
        'print_speed': 2400,
        'travel_speed': 12000,
        'nozzle_temp': 210,
        'bed_temp': 60,
        'relative_e': True,
    },
    save_as='trident_dome',
))
# --- 3D preview (FullControl's Plotly viewer) ---
fc.transform(steps, 'plot', fc.PlotControls(style='tube', color_type='z_gradient', hide_travel=True))
